const manifest = {
  pins: { sdk: 'v2', zod: 'v4', node: '20+', spec: '2026-07-28' },
  server: { tools: ['search-orders', 'lookup-order', 'issue-refund@gated'], resources: ['policy://returns/v14'], prompts: ['triage-ticket'] },
  safety: { approval: 'elicitation', audit: true },
  eval: { gold: 15 },
};
const checks = [
  ['versions pinned', manifest.pins.spec === '2026-07-28' && manifest.pins.sdk === 'v2'],
  ['money gated', manifest.server.tools.some((t) => t.endsWith('@gated'))],
  ['resource versioned', manifest.server.resources.every((r) => /v\d+$/.test(r))],
  ['eval sized', manifest.eval.gold >= 12],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'manifest sound' : 'manifest BROKEN');

